package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** A steward undoes the transfer that brought the person to this sheet, on the sheet-today they
 *  arrived: they are transferred back to the sheet they came from by the transfer's own rules (see
 *  {@link TransferPerson}). Refused: anyone but a steward, a person who did not arrive by transfer,
 *  and any later day. */
public class UndoTransfer {
    public void undo(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            @Val TransferUndoRequest request, People people, Transfers transfers, Settings settings, Sheets sheets,
            Rollup rollup, Out<Person> personOut, Out<Transfer> transferOut)
            throws PersonNotFoundException, InvalidSheetRequestException {
        if (settings.role(sheetId, request.user()) != Role.STEWARD) {
            throw new InvalidSheetRequestException("Only a steward can undo a transfer");
        }
        Person person = people.find(sheetId, personId);
        if (person == null) throw new PersonNotFoundException(personId);
        java.time.LocalDate arrived = transfers.arrivedOn(personId);
        if (person.getOriginSheet() == null || arrived == null) {
            throw new InvalidSheetRequestException("This person did not arrive by a transfer");
        }
        if (!arrived.equals(sheets.today(sheetId))) {
            throw new InvalidSheetRequestException("A transfer can be undone only on the day it arrived");
        }
        new TransferPerson().transfer(sheetId, personId, new TransferRequest(person.getOriginSheet(), request.user()),
                people, transfers, settings, sheets, rollup, personOut, transferOut);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateTransferUndo {
    public void validate(@RequestBody TransferUndoRequest request, Out<TransferUndoRequest> body, Out<Actor> actor) {
        TransferUndoRequest given = request != null ? request : new TransferUndoRequest(null);
        body.set(given);
        actor.set(new Actor(given.user()));
    }
}
package net.officefloor.hq.app.person;

/** Body of undoing the transfer that brought a person to this sheet: who makes the change. */
public record TransferUndoRequest(String user) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** After the transfer back is saved and audited: this sheet's line that the transfer was undone. */
public class RecordTransferUndone {
    public void record(@Val Transfer transfer, Audit audit) {
        audit.record("PERSON_TRANSFER_UNDONE sheet=" + transfer.from() + " by=" + transfer.user()
                + " name=" + transfer.name() + " to=" + transfer.to());
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, type Person } from '../people/usePeople';
import { useRowAction } from '../people/useRowAction';
import { sheetKey } from '../sheet/useSheet';

/**
 * Transferring a person to another sheet: that sheet's id and the button to transfer. Only a steward
 * may; the server refuses a retired person, this sheet's own id, and a name, alias or contact already
 * on the other sheet. The person arrives there with their grades, terms, contact, aliases and claims,
 * and leaves this list.
 */
function PersonTransfer({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [to, setTo] = useState('');
  const transfer = useMutation({
    mutationFn: (toSheet: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/transfer`, { to: toSheet, user }),
    // Everything else on both sheets first (the claims move with the person), then the list the row leaves.
    onSuccess: (_data, toSheet) => {
      void queryClient.invalidateQueries({ queryKey: sheetKey(toSheet.trim()) });
      return queryClient.invalidateQueries({
        queryKey: sheetKey(sheet),
        predicate: (q) => q.queryKey[2] !== peopleKey(sheet)[2],
      });
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const actionTaken = useRowAction(sheet, person.id, transfer.reset);
  return (
    <td>
      <input
        data-testid="person-transfer-to"
        placeholder="Sheet id"
        value={to}
        onChange={(e) => {
          transfer.reset();
          setTo(e.target.value);
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-transfer"
        disabled={transfer.isPending}
        onClick={() => {
          actionTaken();
          transfer.reset();
          transfer.mutate(to);
        }}
      >
        Transfer
      </button>
      {transfer.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          Could not transfer this person (a steward only, to another sheet, not retired, no contact
          already there, names matching at most one person there and not a retired one).
        </span>
      )}
    </td>
  );
}

/**
 * Undoing the transfer that brought the person here: the button to send them back to the sheet they
 * came from, by the transfer's own rules. Only a steward may, on the sheet-today they arrived; the
 * server refuses anyone else, a later day, and a person who did not arrive by transfer.
 */
function PersonTransferUndo({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const undo = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/transfer-undo`, { user }),
    // Both sheets (the claims move back with the person), then the list the row leaves.
    onSuccess: () => {
      if (person.origin) void queryClient.invalidateQueries({ queryKey: sheetKey(person.origin) });
      return queryClient.invalidateQueries({
        queryKey: sheetKey(sheet),
        predicate: (q) => q.queryKey[2] !== peopleKey(sheet)[2],
      });
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const actionTaken = useRowAction(sheet, person.id, undo.reset);
  return (
    <td>
      <button
        type="button"
        data-testid="person-transfer-undo"
        disabled={undo.isPending}
        onClick={() => {
          actionTaken();
          undo.reset();
          undo.mutate();
        }}
      >
        Undo transfer
      </button>
      {undo.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          Could not undo this transfer (a steward only, on the day the person arrived by transfer).
        </span>
      )}
    </td>
  );
}

/** The sheet a transferred person came from; nothing for anyone else. */
function PersonOrigin({ person }: { user: string; sheet: string; person: Person }) {
  return <td data-testid="person-origin">{person.origin ?? ''}</td>;
}

