          undo.mutate();
        }}
      >
        Undo merge
      </button>
      {undo.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          Could not undo the merge (only the steward who made the last merge into this person, on the
          day it was made).
        </span>
      )}
    </td>
  );
}

